class Solution {
  private int[][] grid;

  private void fill(int r, int c, int size, int start) {
    if (size == 1) {
      grid[r][c] = start;
      return;
    }
    int half = size / 2, quad = half * half;
    fill(r, c + half, half, start);
    fill(r + half, c + half, half, start + quad);
    fill(r + half, c, half, start + 2 * quad);
    fill(r, c, half, start + 3 * quad);
  }

  public int[][] specialGrid(int n) {
    int size = 1 << n;
    grid = new int[size][size];
    fill(0, 0, size, 0);
    return grid;
  }
}
